using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
namespace Overclock {
 static class PrecisionPaint {
  public static float Scale(Control c){using(var g=c.CreateGraphics())return g.DpiX/96;}
  public static void Surface(Graphics g,RectangleF r){if(r.Width<2||r.Height<2)return;using(var path=Theme.Angular(r,10)){using(var b=new LinearGradientBrush(r,Color.FromArgb(32,36,40),Color.FromArgb(17,20,22),45))g.FillPath(b,path);var state=g.Save();g.SetClip(path);using(var p=new Pen(Color.FromArgb(9,255,255,255)))for(float x=r.Right-160;x<r.Right+100;x+=6)g.DrawLine(p,x,r.Bottom,x+100,r.Bottom-100);g.Restore(state);using(var p=new Pen(Color.FromArgb(81,86,91)))g.DrawPath(p,path);using(var inner=Theme.Angular(RectangleF.Inflate(r,-2,-2),9))using(var p=new Pen(Color.FromArgb(39,44,48)))g.DrawPath(p,inner);}}
  public static void Ribbon(Graphics g,string text,RectangleF r,float fontSize=22){float width=Math.Min(r.Width-8,Math.Max(160,text.Length*fontSize*.58f+42));using(var path=new GraphicsPath()){path.AddPolygon(new[]{new PointF(r.X+12,r.Y),new PointF(r.X+width,r.Y),new PointF(r.X+width-30,r.Bottom),new PointF(r.X,r.Bottom),new PointF(r.X,r.Y+14)});using(var b=new LinearGradientBrush(r,Color.FromArgb(234,11,37),Color.FromArgb(117,4,13),90))g.FillPath(b,path);using(var p=new Pen(Color.FromArgb(255,70,86)))g.DrawLine(p,r.X+12,r.Y,r.X+width,r.Y);}for(int i=0;i<2;i++)using(var b=new SolidBrush(i==0?Theme.Accent:Theme.PrimaryHover))g.FillPolygon(b,new[]{new PointF(r.X+width+6+i*12,r.Y),new PointF(r.X+width+12+i*12,r.Y),new PointF(r.X+width-18+i*12,r.Bottom),new PointF(r.X+width-24+i*12,r.Bottom)});Text(g,text,fontSize,new RectangleF(r.X+22,r.Y+3,width-26,r.Height-1),Theme.Text,true,true);}
  public static void Text(Graphics g,string text,float px,RectangleF r,Color color,bool bold=false,bool italic=false){using(var f=new Font("Segoe UI",px,(bold?FontStyle.Bold:0)|(italic?FontStyle.Italic:0),GraphicsUnit.Pixel))using(var b=new SolidBrush(color))using(var format=new StringFormat{Trimming=StringTrimming.EllipsisWord,FormatFlags=StringFormatFlags.LineLimit})g.DrawString(text??"",f,b,r,format);}
  public static void Art(Graphics g,string key,RectangleF r){var image=DashboardArt.Get(key);if(image==null){if(key=="native-network"){using(var pen=new Pen(Theme.Secondary,2)){float x=r.Right-95,y=r.Y+35;g.DrawRectangle(pen,x+28,y,30,22);g.DrawLine(pen,x+43,y+22,x+43,y+41);g.DrawLine(pen,x+5,y+41,x+80,y+41);g.DrawLine(pen,x+5,y+41,x+5,y+51);g.DrawLine(pen,x+80,y+41,x+80,y+51);g.DrawRectangle(pen,x-9,y+51,28,22);g.DrawRectangle(pen,x+66,y+51,28,22);}return;}using(var p=new Pen(Theme.Secondary,2)){float x=r.Right-90,y=r.Y+20;g.DrawRectangle(p,x,y,62,48);for(int i=0;i<4;i++){g.DrawLine(p,x-6,y+6+i*11,x,y+6+i*11);g.DrawLine(p,x+62,y+6+i*11,x+68,y+6+i*11);}}return;}Rectangle bounds=DashboardArt.Bounds(key);float factor=Math.Min(r.Width/bounds.Width,r.Height/bounds.Height);var target=new RectangleF(r.Right-bounds.Width*factor,r.Y,bounds.Width*factor,bounds.Height*factor);g.DrawImage(image,target,bounds,GraphicsUnit.Pixel);}
 }
 sealed class SectionPanel:Panel {
  public string Title;public SectionPanel(string title){Title=title;DoubleBuffered=true;BackColor=Theme.Background;Padding=new Padding(14,50,14,14);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;float s=g.DpiX/96;var state=g.Save();g.ScaleTransform(s,s);g.SmoothingMode=SmoothingMode.AntiAlias;PrecisionPaint.Surface(g,new RectangleF(.5f,.5f,Width/s-1,Height/s-1));PrecisionPaint.Ribbon(g,Title,new RectangleF(1,9,Width/s-4,34),20);g.Restore(state);}
 }
 sealed class IdentityBanner:Control {
  public string Caption="",Model="",Summary="",ArtKey,Aside;public IdentityBanner(){DoubleBuffered=true;Height=160;Dock=DockStyle.Top;BackColor=Theme.Background;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;float s=g.DpiX/96,w=Width/s,h=Height/s;var state=g.Save();g.ScaleTransform(s,s);g.SmoothingMode=SmoothingMode.AntiAlias;PrecisionPaint.Surface(g,new RectangleF(.5f,.5f,w-1,h-1));if(ArtKey!=null||Caption=="CPU"||Caption=="GPU"||Caption=="Storage"||Caption=="Network")PrecisionPaint.Art(g,ArtKey??(Caption=="Network"?"native-network":null),new RectangleF(Aside==null?w*.66f:w*.43f,3,Aside==null?w*.33f:w*.25f,h-6));PrecisionPaint.Ribbon(g,Caption,new RectangleF(1,8,w*.60f,35),22);PrecisionPaint.Text(g,Model,24,new RectangleF(22,58,w*(Aside==null?.64f:.43f)-24,62),Theme.Text,true,true);if(Aside!=null)PrecisionPaint.Text(g,Aside,28,new RectangleF(w*.70f,60,w*.28f,h-60),Theme.Text,true);PrecisionPaint.Text(g,Summary,16,new RectangleF(22,h-35,w*.67f-24,28),Theme.Muted);g.Restore(state);}
 }
 sealed class PageHeading:Label {
  public PageHeading(){DoubleBuffered=true;}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;float s=g.DpiX/96;var state=g.Save();g.ScaleTransform(s,s);float w=Width/s,h=Height/s;if(h<50){Branding.DrawLogo(g,new Rectangle(0,0,165,40));PrecisionPaint.Text(g,"Compact monitor  /  expand",24,new RectangleF(185,4,w-190,37),Theme.Text,true,true);g.Restore(state);return;}PrecisionPaint.Text(g,Text,44,new RectangleF(4,0,w-30,h-7),Theme.Text,true,true);float start=Math.Min(w-90,Text.Length*26+26);for(int i=0;i<2;i++)using(var b=new SolidBrush(Theme.Accent))g.FillPolygon(b,new[]{new PointF(start+16+i*20,14),new PointF(start+29+i*20,14),new PointF(start+8+i*20,39),new PointF(start-5+i*20,39)});using(var b=new LinearGradientBrush(new PointF(w*.50f,0),new PointF(w,0),Color.FromArgb(0,Theme.Accent),Theme.Accent))g.FillRectangle(b,w*.5f,h-3,w*.5f,2);for(int i=0;i<2;i++)using(var b=new SolidBrush(i==0?Theme.PrimaryHover:Theme.Accent))g.FillPolygon(b,new[]{new PointF(w-76+i*26,0),new PointF(w-55+i*26,0),new PointF(w-101+i*26,h-3),new PointF(w-123+i*26,h-3)});g.Restore(state);}
 }
 sealed class PageFooter:Label {
  public PageFooter(){DoubleBuffered=true;}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Theme.Background);float s=g.DpiX/96;var state=g.Save();g.ScaleTransform(s,s);float w=Width/s,h=Height/s;using(var p=new Pen(Theme.Line))g.DrawLine(p,0,0,w,0);using(var p=new Pen(Theme.Accent,1))g.DrawLine(p,w*.45f,1,w,1);for(int i=0;i<2;i++)using(var b=new SolidBrush(Theme.Accent))g.FillPolygon(b,new[]{new PointF(19+i*15,15),new PointF(29+i*15,15),new PointF(10+i*15,37),new PointF(i*15,37)});PrecisionPaint.Text(g,Text,14,new RectangleF(53,16,w-65,h-17),Theme.Text);g.Restore(state);}
 }
 static class GridData {
  public static void Apply(DataGridView grid,System.Collections.Generic.List<object[]> data){int top=grid.FirstDisplayedScrollingRowIndex;string chosen=grid.SelectedRows.Count==0?null:Convert.ToString(grid.SelectedRows[0].Cells[0].Value);grid.SuspendLayout();try{while(grid.Rows.Count>data.Count)grid.Rows.RemoveAt(grid.Rows.Count-1);for(int i=0;i<data.Count;i++){if(i>=grid.Rows.Count)grid.Rows.Add();for(int j=0;j<data[i].Length&&j<grid.Columns.Count;j++)if(!object.Equals(grid.Rows[i].Cells[j].Value,data[i][j]))grid.Rows[i].Cells[j].Value=data[i][j];grid.Rows[i].Cells[0].ToolTipText=Convert.ToString(data[i][0]);if(chosen!=null&&Convert.ToString(data[i][0])==chosen)grid.Rows[i].Selected=true;}if(top>=0&&top<grid.Rows.Count)grid.FirstDisplayedScrollingRowIndex=top;}finally{grid.ResumeLayout();}}
 }
}